// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String(String(dma_detail1.get("comNm"))).split("&").join("&")); } },
        { childId: "__rb1", fn: function () { return String(String(String(dma_detail1.get("comEngNm"))).split("&").join("&")); } },
        { childId: "__rb2", fn: function () { return String(String(String(dma_detail1.get("comAbbrv"))).split("&").join("&")); } },
        { childId: "__rb3", fn: function () { return String(String(String(dma_detail1.get("comEngAbbrv"))).split("&").join("&")); } },
        { childId: "__rb12", fn: function () { return String(String(dma_detail1.get("acntclsMmdd1"))); } },
        { childId: "btn_homePagePoup", fn: function () { return String(dma_detail1.get("hpage")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

