        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_homePagePoup_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.homePagePoup('' + dma_detail1.get("hpage") + '')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst90005.btn_homePagePoup_onclick' }); }
