*/
scwin.homePagePoup = function (url) {
    /* sdd-asis-lifecycle:begin homePagePoup — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { id: 'popup' }, {});
    /* sdd-asis-lifecycle:end */
};
